const http = require('http');

const baseUrl = 'http://localhost:3001/mcp/write_file';
const projectRoot = $vars.projectRoot || '.';
const authToken = $vars.authToken || '';

const filePath = typeof $path !== 'undefined' ? String($path) : '';
const fileContent = typeof $content !== 'undefined' ? String($content) : '';

if (!filePath) return 'Error: path is required';

const body = JSON.stringify({
  parameters: { path: filePath, content: fileContent }
});

const bodyBuffer = Buffer.from(body, 'utf8');

return new Promise((resolve) => {
  const req = http.request(baseUrl, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      'Content-Length': bodyBuffer.length,
      'Authorization': 'Bearer ' + authToken,
      'X-Project-Root': encodeURIComponent(projectRoot)
    }
  }, (res) => {
    let data = '';
    res.on('data', chunk => data += chunk);
    res.on('end', () => {
      if (res.statusCode !== 200) {
        resolve('Error: ' + res.statusCode + ' - ' + data.slice(0, 300));
      } else {
        resolve('File ' + filePath + ' written successfully.');
      }
    });
  });

  req.on('error', (err) => resolve('Error: ' + err.message));
  req.write(bodyBuffer);
  req.end();
});
